# Test each component; infer heading by the three-cell bar and stem direction.
grid=['00000000000','00200000000','02220002220','00000000200','00222000000','00020000000','00000022200','00200002000','02220000000','00000000000']
R,C=len(grid),len(grid[0]); seen=set(); out=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]=='2' and (r,c) not in seen:
   st=[(r,c)]; seen.add((r,c)); comp=[]
   while st:
    x,y=st.pop(); comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     p=x+dx,y+dy
     if 0<=p[0]<R and 0<=p[1]<C and grid[p[0]][p[1]]=='2' and p not in seen: seen.add(p); st.append(p)
   out.append(comp)
for i,co in enumerate(out):
  minr=min(x for x,y in co); maxr=max(x for x,y in co); minc=min(y for x,y in co); maxc=max(y for x,y in co)
  # T stem points to vertical side: if three-cell row and singleton above => up, below => down; three-cell col analog
  if len({x for x,y in co})==2:
    bar=[(x,y) for x,y in co if sum(a==x for a,b in co)==3][0][0]
    stemrow=next(x for x,y in co if sum(a==x for a,b in co)==1)
    orient='up' if stemrow<bar else 'down'
  else:
    bar=[(x,y) for x,y in co if sum(b==y for a,b in co)==3][0][1]
    stemcol=next(y for x,y in co if sum(b==y for a,b in co)==1)
    orient='left' if stemcol<bar else 'right'
  print(i, (minr,minc),orient)
